#include "FireSimulation.h"
#include "WorldCore/ChunkState.h"
#include "WorldPhaseW3_Event/WorldEventSubsystem.h"
void UFireSimulation::SimulateChunk(UChunkState* C,float Days,float Wind,FVector2D Dir){if(!C||Days<=0)return;TArray<int32> Burning;for(int32 I=0;I<C->Cells.Num();++I)if(C->Cells[I].Biomass.bIsBurning)Burning.Add(I);for(int32 I:Burning){FChunkCell& Cell=C->Cells[I];const float Burn=FMath::Min(Cell.Biomass.Biomass,Cell.Biomass.Biomass*0.3f*Days);Cell.Biomass.Biomass=FMath::Max(0.0f,Cell.Biomass.Biomass-Burn);Cell.Biomass.Health=FMath::Max(0.0f,Cell.Biomass.Health-0.5f*Days);Cell.bIsDirty=true;if(Cell.Biomass.Biomass<MinBiomassToBurn){Cell.Biomass.bIsBurning=false;Cell.bHasFire=false;BroadcastFireEvent(C,EWorldEventType::FireExtinguished,0.0f,I);}else SpreadFire(C,I,Days,Dir.GetSafeNormal()*FMath::Max(0.0f,Wind));}C->MarkDirty();}
bool UFireSimulation::TryIgnite(UChunkState* C,int32 I){if(!C||!C->Cells.IsValidIndex(I))return false;FChunkCell& X=C->Cells[I];if(X.Biomass.Biomass<MinBiomassToBurn||X.SoilMoisture>0.7f||X.Biomass.bIsBurning)return false;X.Biomass.bIsBurning=true;X.bHasFire=true;X.bIsDirty=true;C->MarkDirty();BroadcastFireEvent(C,EWorldEventType::FireStarted,X.Biomass.Biomass,I);return true;}
void UFireSimulation::ExtinguishCell(UChunkState* C,int32 I){if(!C||!C->Cells.IsValidIndex(I))return;FChunkCell& X=C->Cells[I];const bool Was=X.Biomass.bIsBurning;X.Biomass.bIsBurning=false;X.bHasFire=false;X.SoilMoisture=FMath::Min(1.0f,X.SoilMoisture+0.3f);X.bIsDirty=true;C->MarkDirty();if(Was)BroadcastFireEvent(C,EWorldEventType::FireExtinguished,0,I);}
void UFireSimulation::SpreadFire(UChunkState* C,int32 I,float Days,FVector2D Dir){const int32 N=FMath::RoundToInt(FMath::Sqrt((float)C->Cells.Num()));if(N<=0)return;const int32 X=I%N,Y=I/N;const float WindFactor=1.0f+FMath::Clamp(Dir.Size(),0.0f,2.0f)*0.5f;const float Prob=FMath::Clamp(BaseSpreadRate*Days*WindFactor,0.0f,1.0f);const int32 XY[4][2]={{X-1,Y},{X+1,Y},{X,Y-1},{X,Y+1}};for(const auto& P:XY){if(P[0]<0||P[1]<0||P[0]>=N||P[1]>=N)continue;const int32 J=P[1]*N+P[0];FChunkCell& A=C->Cells[J];if(A.Biomass.bIsBurning||A.Biomass.Biomass<MinBiomassToBurn||A.SoilMoisture>0.7f)continue;const FVector2D Direction((float)(P[0]-X),(float)(P[1]-Y));const float Downwind=FMath::Max(0.0f,FVector2D::DotProduct(Direction,Dir.GetSafeNormal()));const float PFire=FMath::Clamp(Prob*(1.0f+Downwind),0.0f,1.0f);const uint32 Seed=HashCombine(GetTypeHash(C->Coordinate),HashCombine(::GetTypeHash(I),HashCombine(::GetTypeHash(J),::GetTypeHash(FMath::FloorToInt(C->Metadata.LastUpdateDay*1000.0f)))));FRandomStream R((int32)Seed);if(R.FRand()<PFire){A.Biomass.bIsBurning=true;A.bHasFire=true;A.bIsDirty=true;BroadcastFireEvent(C,EWorldEventType::FireSpread,A.Biomass.Biomass,J);}}}
void UFireSimulation::BroadcastFireEvent(UChunkState* C,EWorldEventType T,float M,int32 I){if(!C)return;FWorldEvent E;E.Type=T;E.ChunkCoord=C->Coordinate;E.Magnitude=M;E.NumericPayload.Add(TEXT("CellIndex"),(float)I);if(UWorld* W=GetWorld())if(UWorldEventSubsystem* S=W->GetSubsystem<UWorldEventSubsystem>())S->BroadcastEvent(E);}
